document.querySelectorAll('[data-lab="BM02-I1"]').forEach(root=>{const zh=root.dataset.lang==='zh',get=s=>root.querySelector('[data-field="'+s+'"]'),nEl=get('length'),pEl=get('probability');function update(){const n=Number(nEl.value),m=n-1,p=Number(pEl.value)/100,final=Math.pow(p,m);get('lengthValue').textContent=n;get('probabilityValue').textContent=(p*100).toFixed(1)+'%';let marks='';[0,25,50,75,100].forEach(v=>{const y=280-2.2*v;marks+='<path d="M75 '+y+' H550" stroke="#d9dfdc"/><text x="62" y="'+(y+7)+'" text-anchor="end" font-size="20">'+v+'</text>';});[0,Math.round(m/2),m].filter((v,i,a)=>a.indexOf(v)===i).forEach(v=>{const x=75+475*v/m;marks+='<text x="'+x+'" y="309" text-anchor="middle" font-size="20">'+v+'</text>';});const pts=Array.from({length:m+1},(_,k)=>(75+475*k/m).toFixed(2)+','+(280-220*Math.pow(p,k)).toFixed(2)).join(' ');get('plot').innerHTML='<rect width="600" height="360" rx="16" fill="#f5f6ee"/><g fill="#153b43" font-family="system-ui,sans-serif">'+marks+'<path d="M75 50 V280 H550" fill="none" stroke="#153b43" stroke-width="2"/><polyline points="'+pts+'" fill="none" stroke="#168b83" stroke-width="4"/><circle cx="550" cy="'+(280-220*final)+'" r="6" fill="#c46c42"/><text x="75" y="32" font-size="20">'+(zh?'完整正确链（%）':'Complete correct chains (%)')+'</text><text x="310" y="345" text-anchor="middle" font-size="21">'+(zh?'增长轮数':'Extension cycles')+'</text></g>';get('result').textContent=zh?'目标为'+n+'个残基，需要'+m+'轮增长。完整正确比例约为'+(final*100).toFixed(2)+'%。若起初有10000条链，按此比例折算约有'+Math.round(10000*final)+'条仍完全正确；这是比例模型的期望数量。':'A target of '+n+' residues requires '+m+' extension cycles. About '+(final*100).toFixed(2)+'% remain fully correct. Starting with 10,000 chains, the model gives an expected count of about '+Math.round(10000*final)+' correct chains.';}nEl.addEventListener('input',update);pEl.addEventListener('input',update);get('reset').addEventListener('click',()=>{nEl.value=50;pEl.value=99;update();});update();});